const stream = await tobub.observe.start({
  source: {
    type: 'dom',
    selector: '.chat-item',
    fields: [
      { name: 'id', source: { attr: 'data-id' } },
      { name: 'text', selector: '.message', source: 'text', transforms: [{ type: 'trim' }, { type: 'normalizeWhitespace' }] }
    ]
  },
  filter: { path: 'text', op: 'exists' },
  dedupe: { keyPath: 'id' },
  buffer: { maxItems: 1000, overflow: 'drop-oldest' }
});

